(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-936":{scenario:{company:"Công ty CP Bao bì Đông Phong",supervisor:{name:"Vũ Hải Yến",role:{vi:"Trưởng ban Phát triển bền vững",en:"Head of Sustainability"}},ref_code:"GHG-INV-25",title:{vi:"Đúng phạm vi. Đúng đơn vị. Báo cáo không tẩy xanh.",en:"Right scope. Right units. No greenwashing."},brief:{vi:"Bạn hoàn thiện bảng kiểm kê khí nhà kính năm 2025 GHG-INV-25 của nhà máy. Máy phát điện diesel do công ty sở hữu đốt 42000 lít dầu và cấp 150000 kWh cho nhà máy; điện mua từ lưới quốc gia là 1240000 kWh, hệ số phát thải lưới mô phỏng 0.68 tCO2e/MWh. Đối chiếu bảng nháp với hồ sơ kiểm kê đã duyệt, sửa phạm vi phát thải của máy phát và phát thải phạm vi 2 theo phương pháp dựa trên vị trí, rồi lập báo cáo có căn cứ.",en:"You are finalizing the plant's 2025 greenhouse gas inventory GHG-INV-25. Company-owned diesel generators burned 42000 liters of fuel and supplied 150000 kWh to the plant; electricity bought from the national grid was 1240000 kWh, training grid emission factor 0.68 tCO2e/MWh. Compare the draft with the approved inventory file, correct the emission scope of the generators and the location-based Scope 2 emissions, then write an evidence-based report."},reference_title:{vi:"Hồ sơ kiểm kê khí nhà kính đã duyệt · GHG-INV-25",en:"Approved GHG inventory file · GHG-INV-25"},fields:[{id:"GEN_SCOPE",label:{vi:"Phạm vi phát thải máy phát diesel",en:"Diesel generator emission scope"},initial:"SCOPE-2",expected:"SCOPE-1",choices:["SCOPE-1","SCOPE-2","SCOPE-3"],reference:"Sổ ranh giới & nguồn phát thải",hint:{vi:"Đốt nhiên liệu trong thiết bị do doanh nghiệp sở hữu hoặc kiểm soát là phát thải trực tiếp, dù sản phẩm tạo ra là điện.",en:"Fuel burned in equipment the company owns or controls is a direct emission, even when it produces electricity."}},{id:"S2_TCO2E",label:{vi:"Phát thải phạm vi 2 dựa trên vị trí (tCO2e)",en:"Location-based Scope 2 (tCO2e)"},initial:"945.2",expected:"843.2",reference:"Bảng tính phát thải phạm vi 2",ref_value:{vi:"Điện mua từ lưới 1240000 kWh; điện tự phát của máy phát 150000 kWh; hệ số lưới 0.68 tCO2e/MWh (mô phỏng)",en:"Purchased grid electricity 1240000 kWh; self-generated power 150000 kWh; grid factor 0.68 tCO2e/MWh (training)"},hint:{vi:"Chỉ điện mua từ lưới thuộc phạm vi 2; điện do máy phát của công ty tạo ra đã nằm trong phát thải trực tiếp, không cộng lại.",en:"Only purchased grid power is Scope 2; power from the company generator is already a direct emission and must not be added again."}}],sop32:{vi:"Phạm vi 2 dựa trên vị trí = điện mua từ lưới (đổi kWh sang MWh bằng cách chia 1000) x hệ số phát thải lưới (mô phỏng 0.68 tCO2e/MWh); làm tròn 1 chữ số thập phân. Không cộng điện tự phát của máy phát sở hữu.",en:"Location-based Scope 2 = purchased grid electricity (convert kWh to MWh by dividing by 1000) x grid emission factor (training 0.68 tCO2e/MWh); round to 1 decimal place. Do not add self-generated power from owned generators."},context:{label:"BẢNG KIỂM KÊ KNK / GHG-INV-25",metrics:[{label:{vi:"Dầu diesel máy phát",en:"Generator diesel"},value:"42,000 L"},{label:{vi:"Điện mua từ lưới",en:"Purchased grid power"},value:"1,240,000 kWh"},{label:{vi:"Hệ số lưới mô phỏng",en:"Training grid factor"},value:"0.68 tCO2e/MWh"}]},crisis:{vi:"Giám đốc Tài chính nhắn: “Bỏ máy phát diesel và xưởng in ra khỏi ranh giới báo cáo đi cho tổng phát thải giảm 18%. Tuần sau ngân hàng xét khoản vay xanh, không ai soi kỹ đâu.”",en:"The CFO texts: “Drop the diesel generators and the print shop from the reporting boundary so total emissions fall 18%. The bank reviews our green loan next week and nobody will look closely.”"},options:{safe:{vi:"Giữ ranh giới theo phương pháp kiểm soát vận hành đã công bố, báo Trưởng ban Phát triển bền vững và Ủy ban kiểm toán; mọi thay đổi ranh giới phải có căn cứ, tính lại năm cơ sở và công bố minh bạch.",en:"Keep the published operational control boundary and inform the Head of Sustainability and the audit committee; any boundary change needs a basis, base-year recalculation and transparent disclosure."},shortcut:{vi:"Loại máy phát và xưởng in khỏi ranh giới để kịp hồ sơ vay xanh, giải thích sau nếu bị hỏi.",en:"Remove the generators and print shop from the boundary for the loan file and explain later if asked."},wait:{vi:"Không trả lời, gửi bảng kiểm kê nháp như hiện tại và chờ ngân hàng tự phát hiện.",en:"Do not answer, send the draft inventory as is and wait for the bank to find the issue."}},questions:{vi:["Vì sao phát thải máy phát diesel thuộc SCOPE-1 mà không phải SCOPE-2? Nguyên tắc nào của GHG Protocol làm căn cứ?","Trình bày cách tính phát thải phạm vi 2 và rủi ro tẩy xanh nếu thu hẹp ranh giới để làm đẹp số liệu."],en:["Why are diesel generator emissions SCOPE-1 rather than SCOPE-2? Which GHG Protocol principle supports this?","Explain how you calculated Scope 2 and the greenwashing risk of narrowing the boundary to flatter the figures."]},hints:{vi:["So từng nguồn phát thải với tiêu chí trực tiếp hay gián tiếp trong sổ ranh giới, đánh dấu dòng phân loại sai.","Đổi kWh sang MWh trước khi nhân hệ số lưới theo SOP mục 3.2.","Đọc lại SOP mục 4.2: ranh giới kiểm kê chỉ thay đổi khi có căn cứ, tính lại năm cơ sở và được phê duyệt."],en:["Check each source against the direct or indirect criteria in the boundary register and flag the wrong line.","Convert kWh to MWh before applying the grid factor in SOP 3.2.","Re-read SOP 4.2: the inventory boundary changes only with a basis, base-year recalculation and approval."]}},learning:{summary:{vi:"Chuyên viên báo cáo phát triển bền vững và kiểm kê khí nhà kính thu thập dữ liệu môi trường, xã hội, quản trị (ESG), tính phát thải phạm vi 1, 2, 3, lập báo cáo theo GHG Protocol, ISO 14064-1, GRI, IFRS S2 và chuẩn bị hồ sơ cho thẩm tra độc lập. Nghề đòi hỏi tư duy dữ liệu chặt chẽ, hiểu quy trình sản xuất, nắm quy định kiểm kê khí nhà kính của Việt Nam và giữ chính trực trước áp lực tẩy xanh.",en:"An ESG and carbon accounting specialist collects environmental, social and governance data, calculates Scope 1, 2 and 3 emissions, reports under the GHG Protocol, ISO 14064-1, GRI and IFRS S2, and prepares files for independent verification. The role requires rigorous data thinking, understanding of operations, knowledge of Vietnam's GHG inventory rules and integrity under greenwashing pressure."},responsibilities:{vi:["Xác định ranh giới tổ chức, ranh giới hoạt động và danh mục nguồn phát thải.","Thu thập dữ liệu hoạt động, chọn hệ số phát thải và tính phát thải phạm vi 1, 2, 3.","Lập báo cáo kiểm kê khí nhà kính và báo cáo phát triển bền vững theo GRI, IFRS S1, S2.","Phối hợp đơn vị thẩm tra độc lập, giải trình dữ liệu và khắc phục phát hiện.","Đề xuất lộ trình giảm phát thải, mục tiêu dựa trên khoa học và theo dõi tiến độ."],en:["Set organizational and operational boundaries and the list of emission sources.","Collect activity data, select emission factors and calculate Scope 1, 2 and 3.","Prepare GHG inventory and sustainability reports under GRI and IFRS S1, S2.","Work with independent verifiers, explain data and close findings.","Propose decarbonization roadmaps and science-based targets and track progress."]},competencies:[{name:{vi:"Kế toán khí nhà kính",en:"GHG accounting"},desc:{vi:"Phân loại nguồn đúng phạm vi, chọn hệ số phù hợp và tính phát thải nhất quán qua các năm.",en:"Classify sources into the right scope, choose suitable factors and calculate consistently over years."}},{name:{vi:"Quản lý dữ liệu ESG",en:"ESG data management"},desc:{vi:"Thiết kế luồng thu thập, kiểm soát chất lượng và lưu vết dữ liệu từ nhiều bộ phận.",en:"Design collection flows, quality checks and audit trails for data from many departments."}},{name:{vi:"Chuẩn mực công bố",en:"Disclosure standards"},desc:{vi:"Áp dụng GRI, IFRS S1, S2 và bảng câu hỏi CDP để công bố đầy đủ, so sánh được.",en:"Apply GRI, IFRS S1, S2 and the CDP questionnaire for complete, comparable disclosure."}},{name:{vi:"Phân tích giảm phát thải",en:"Decarbonization analysis"},desc:{vi:"Lập đường cong chi phí giảm phát thải biên (MACC) và đánh giá phương án tiết kiệm năng lượng.",en:"Build marginal abatement cost curves (MACC) and assess energy efficiency options."}},{name:{vi:"Chính trực chống tẩy xanh",en:"Anti-greenwashing integrity"},desc:{vi:"Từ chối làm đẹp số liệu, công bố cả điểm yếu và báo cáo áp lực sai lệch lên cấp có thẩm quyền.",en:"Refuse to dress up figures, disclose weaknesses too and escalate pressure to misstate."}}],knowledge:{vi:["GHG Protocol Corporate Standard và Scope 2 Guidance (phương pháp dựa trên vị trí và dựa trên thị trường).","ISO 14064-1:2018 về định lượng, báo cáo khí nhà kính cấp tổ chức và ISO 14064-3 về thẩm định, thẩm tra.","Chuẩn mực IFRS S1, IFRS S2 của ISSB và bộ tiêu chuẩn GRI (GRI 305 Phát thải).","Nghị định 06/2022/NĐ-CP về giảm nhẹ phát thải khí nhà kính và bảo vệ tầng ô-dôn; danh mục cơ sở phải kiểm kê (Quyết định 01/2022/QĐ-TTg và các lần cập nhật).","Hướng dẫn IPCC 2006 về kiểm kê khí nhà kính và giá trị tiềm năng nóng lên toàn cầu (GWP) theo báo cáo đánh giá của IPCC.","GHG Protocol Scope 3 Standard với 15 hạng mục và hướng dẫn đặt mục tiêu của SBTi."],en:["GHG Protocol Corporate Standard and Scope 2 Guidance (location-based and market-based methods).","ISO 14064-1:2018 on organization-level GHG quantification and reporting, and ISO 14064-3 on validation and verification.","ISSB standards IFRS S1, IFRS S2 and the GRI Standards (GRI 305 Emissions).","Decree 06/2022/ND-CP on GHG mitigation and ozone layer protection; the list of facilities required to inventory (Decision 01/2022/QD-TTg and updates).","2006 IPCC Guidelines for GHG inventories and global warming potential (GWP) values from IPCC assessment reports.","The GHG Protocol Scope 3 Standard with 15 categories and SBTi target-setting guidance."]},tools:["Phần mềm quản lý dữ liệu ESG","Cơ sở dữ liệu hệ số phát thải IPCC EFDB","Microsoft Excel và Power BI","Bảng câu hỏi CDP","Công cụ tính phát thải của GHG Protocol"],kpis:{vi:["Tỷ lệ dữ liệu hoạt động có chứng từ gốc và truy xuất được (mục tiêu 100%).","Số phát hiện trọng yếu của đơn vị thẩm tra (mục tiêu bằng 0).","Mức giảm cường độ phát thải (tCO2e trên đơn vị sản phẩm) so với năm cơ sở.","Tỷ lệ báo cáo nộp đúng hạn theo quy định và cam kết với nhà đầu tư."],en:["Share of activity data backed by source documents and traceable (target 100%).","Material findings from the verifier (target zero).","Reduction in emission intensity (tCO2e per unit of output) against the base year.","Share of reports filed on time under regulations and investor commitments."]},day:[{time:"08:00",vi:"Kiểm tra dữ liệu điện, nhiên liệu, môi chất lạnh tháng trước từ các nhà máy.",en:"Check last month's electricity, fuel and refrigerant data from the plants."},{time:"10:00",vi:"Đối chiếu hóa đơn điện, phiếu xuất dầu với số liệu trên hệ thống và xử lý chênh lệch.",en:"Match power bills and fuel issue slips with system data and resolve gaps."},{time:"13:30",vi:"Tính phát thải phạm vi 1, 2, cập nhật hệ số phát thải và ghi rõ nguồn trích dẫn.",en:"Calculate Scope 1 and 2, update emission factors and cite their sources."},{time:"15:30",vi:"Họp với bộ phận mua hàng về dữ liệu phát thải nhà cung cấp cho phạm vi 3.",en:"Meet procurement about supplier emissions data for Scope 3."},{time:"17:00",vi:"Cập nhật nhật ký giả định và lưu bằng chứng cho hồ sơ thẩm tra.",en:"Update the assumptions log and file evidence for verification."}],mistakes:{vi:["Xếp nhiên liệu đốt tại máy phát của doanh nghiệp vào phạm vi 2 thay vì phạm vi 1.","Nhầm đơn vị kWh và MWh, làm phát thải sai lệch 1000 lần.","Thu hẹp ranh giới hoặc bỏ nguồn phát thải lớn để làm đẹp báo cáo, gây rủi ro tẩy xanh."],en:["Putting fuel burned in the company's own generators into Scope 2 instead of Scope 1.","Confusing kWh and MWh so emissions are off by a factor of 1000.","Narrowing the boundary or dropping large sources to flatter the report, creating greenwashing risk."]},career:[{vi:"Chuyên viên dữ liệu môi trường",en:"Environmental data analyst"},{vi:"Chuyên viên kiểm kê khí nhà kính & báo cáo ESG",en:"GHG inventory & ESG reporting specialist"},{vi:"Trưởng nhóm phát triển bền vững",en:"Sustainability team lead"},{vi:"Giám đốc Phát triển bền vững (CSO)",en:"Chief Sustainability Officer (CSO)"}],glossary:[{term:"Scope 1",vi:"Phát thải trực tiếp từ nguồn doanh nghiệp sở hữu hoặc kiểm soát: lò hơi, máy phát, xe, rò rỉ môi chất lạnh.",en:"Direct emissions from sources the company owns or controls: boilers, generators, vehicles, refrigerant leaks."},{term:"Scope 2",vi:"Phát thải gián tiếp từ điện, hơi, nhiệt và lạnh mua về để tiêu thụ.",en:"Indirect emissions from purchased electricity, steam, heat and cooling consumed."},{term:"Scope 3",vi:"Các phát thải gián tiếp khác trong chuỗi giá trị, gồm 15 hạng mục theo GHG Protocol.",en:"Other indirect value-chain emissions across the 15 GHG Protocol categories."},{term:"tCO2e",vi:"Tấn CO2 tương đương: quy đổi các khí nhà kính về CO2 theo hệ số tiềm năng nóng lên toàn cầu.",en:"Tonnes of CO2 equivalent: greenhouse gases converted to CO2 using global warming potentials."},{term:"Greenwashing",vi:"Tẩy xanh: trình bày sai lệch hoặc phóng đại thành tích môi trường để tạo ấn tượng tốt.",en:"Misleading or exaggerated presentation of environmental performance to look good."}],quiz:[{q:{vi:"Xe tải giao hàng do công ty sở hữu đốt dầu diesel. Phát thải này thuộc phạm vi nào?",en:"Company-owned delivery trucks burn diesel. Which scope do these emissions belong to?"},options:{vi:["Phạm vi 2","Phạm vi 3","Phạm vi 1","Không phải báo cáo"],en:["Scope 2","Scope 3","Scope 1","Not reportable"]},answer:2,explain:{vi:"Nhiên liệu đốt trong phương tiện doanh nghiệp sở hữu hoặc kiểm soát là phát thải trực tiếp phạm vi 1.",en:"Fuel burned in vehicles the company owns or controls is a direct Scope 1 emission."}},{q:{vi:"Nhà máy dùng 2500000 kWh điện lưới, hệ số mô phỏng 0.7 tCO2e/MWh. Phát thải phạm vi 2 dựa trên vị trí là bao nhiêu?",en:"A plant uses 2500000 kWh of grid power with a training factor of 0.7 tCO2e/MWh. What is location-based Scope 2?"},options:{vi:["1750 tCO2e","1750000 tCO2e","3571 tCO2e","175 tCO2e"],en:["1750 tCO2e","1750000 tCO2e","3571 tCO2e","175 tCO2e"]},answer:0,explain:{vi:"Đổi đơn vị: 2500000 kWh = 2500 MWh; nhân hệ số: 2500 x 0.7 = 1750 tCO2e.",en:"2500000 kWh = 2500 MWh; 2500 x 0.7 = 1750 tCO2e."}},{q:{vi:"Lãnh đạo muốn bỏ một nhà máy phát thải lớn khỏi ranh giới để báo cáo giảm phát thải. Bạn làm gì?",en:"Management wants to drop a high-emitting plant from the boundary to report a reduction. What do you do?"},options:{vi:["Đồng ý vì báo cáo là tự nguyện","Giữ ranh giới nhất quán, báo cáo cấp có thẩm quyền; thay đổi phải có căn cứ, tính lại năm cơ sở và công bố","Bỏ nhà máy nhưng ghi chú nhỏ cuối trang","Chờ đơn vị thẩm tra tự quyết định"],en:["Agree because reporting is voluntary","Keep a consistent boundary and escalate; changes need a basis, base-year recalculation and disclosure","Drop the plant with a small footnote","Let the verifier decide"]},answer:1,explain:{vi:"Nguyên tắc nhất quán và minh bạch yêu cầu ranh giới ổn định; cắt nguồn lớn để làm đẹp số liệu là tẩy xanh.",en:"Consistency and transparency require a stable boundary; cutting large sources to flatter figures is greenwashing."}},{q:{vi:"Chuẩn mực nào của ISSB quy định công bố thông tin liên quan đến khí hậu?",en:"Which ISSB standard sets climate-related disclosure requirements?"},options:{vi:["IFRS 9","IAS 16","ISO 9001","IFRS S2"],en:["IFRS 9","IAS 16","ISO 9001","IFRS S2"]},answer:3,explain:{vi:"IFRS S2 quy định công bố rủi ro, cơ hội khí hậu và phát thải phạm vi 1, 2, 3; IFRS S1 là yêu cầu chung về bền vững.",en:"IFRS S2 covers climate risks, opportunities and Scope 1, 2, 3 emissions; IFRS S1 sets general sustainability requirements."}}],tools_en:["ESG data management software","IPCC EFDB emission factor database","Microsoft Excel and Power BI","CDP questionnaire","GHG Protocol emission calculation tools"]}}})})(window.KKR);
